export type GuideGroup = 'public' | 'student' | 'teacher' | 'admin'

export interface GuideEntry {
  slug: string
  group: GuideGroup
  title: { en: string; ar: string }
  route: string
  linkRoute?: string
  purpose: { en: string; ar: string }
  instructions: { en: string[]; ar: string[] }
  permissions: { en: string; ar: string }
  integrations: { en: string; ar: string }
  connects: { en: string; ar: string }
}

const make = (
  slug: string,
  group: GuideGroup,
  title: [string, string],
  route: string,
  purpose: [string, string],
  instructions: [string[], string[]],
  permissions: [string, string],
  integrations: [string, string],
  connects: [string, string],
  linkRoute?: string,
): GuideEntry => ({
  slug, group, title: { en: title[0], ar: title[1] }, route,
  ...(linkRoute ? { linkRoute } : {}),
  purpose: { en: purpose[0], ar: purpose[1] },
  instructions: { en: instructions[0], ar: instructions[1] },
  permissions: { en: permissions[0], ar: permissions[1] },
  integrations: { en: integrations[0], ar: integrations[1] },
  connects: { en: connects[0], ar: connects[1] },
})

