export const GUIDE_GROUPS: GuideGroup[] = ['public', 'student', 'teacher', 'admin']

export function getScreenshotPath(slug: string, availableSlugs: ReadonlySet<string>) {
  return availableSlugs.has(slug) ? `/tips/screens/${slug}.png` : null
}

export function canAccessTips(role: string) {
  return role === 'ADMIN'
}

export function validateRegistry(entries: readonly GuideEntry[] = TIPS_REGISTRY): string[] {
  const errors: string[] = []
  const seen = new Set<string>()
  for (const entry of entries) {
    if (!entry.slug || seen.has(entry.slug)) errors.push(`Duplicate or empty screenshot slug: ${entry.slug}`)
    seen.add(entry.slug)
    if (!entry.route.startsWith('/')) errors.push(`Route must be absolute: ${entry.slug}`)
    if (!entry.title.en || !entry.title.ar || !entry.purpose.en || !entry.purpose.ar) {
      errors.push(`Missing bilingual title or purpose: ${entry.slug}`)
    }
    if (!entry.instructions.en.length || !entry.instructions.ar.length) {
      errors.push(`Missing bilingual instructions: ${entry.slug}`)
    }
  }
  return errors
}